## 根因分析

我仔细读了 `uart_ll.h` 和 `uart_hw.h` 中 BK7258 UART 寄存器的完整定义，确认：

- `int_status` (offset 0x24) 是 "write-1-to-clear"（W1C）
- `int_enable` (offset 0x20) 是 per-bit gate，只有 enabled 的 bit 才会送到 NVIC
- SDK 的 `uart_hal_init_uart()` 会调用 `uart_ll_set_rx_fifo_threshold(hw, id, UART_RX_FIFO_THRESHOLD)` 设置阈值 = **0x40（=64）**
- **Zephyr 驱动从未设置 rx_fifo_threshold**

**关键线索**：如果你在 `uart_bk7258_init()` 中没有初始化 `fifo_config.rx_fifo_threshold`（bits [8:15]），硬件的 reset 值很可能是 **0**。这意味着 `rx_fifo_need_read` 的判断条件是 `rx_fifo_count >= threshold`，而 threshold = 0 → `count >= 0` **永远为真**。你在 `irq_rx_enable` 甚至 `irq_update` 里 W1C 清掉 flag，硬件立即把它重新置回 1，因为条件一直满足。这就是风暴的根因。

---

## 建议的 5 步操作

### 第一步：诊断打点验证

在 `uart_bk7258_irq_update` 内加单字符打点，区分 int_status 的 RX bits 是什么：

```c
static int uart_bk7258_irq_update(const struct device *dev)
{
    const struct uart_bk7258_config *cfg = dev->config;
    struct uart_bk7258_data *data = dev->data;

    data->irq_status = sys_read32(cfg->base + BK7258_UART_INT_FLAG_OFFSET);

    /* 单字符诊断：1=bit1, 6=bit6, .=none, *=both, O=other */
    if (data->irq_status & 0x02)
        uart_bk7258_poll_out(dev, '1');
    else if (data->irq_status & 0x40)
        uart_bk7258_poll_out(dev, '6');
    else if (data->irq_status)
        uart_bk7258_poll_out(dev, 'O');
    else
        uart_bk7258_poll_out(dev, '.');

    sys_write32(data->irq_status & 0xFF,
                cfg->base + BK7258_UART_INT_FLAG_OFFSET);

    return 1;   /* 等第二步再改 */
}
```

如果打印出连续 `1` 或 `*`，说明 bit1 确实被硬件反复重新置位 — 这就是 threshold=0 问题。

### 第二步：修复 `irq_update` 返回真实 pending

```c
/* 改前 */
return 1;

/* 改后 — 返回保留的 int_status (Zephyr API 期望的真实状态) */
return data->irq_status;
```

### 第三步：修复 `irq_is_pending` 使用 irq_status

```c
/* 改前 — 依赖 FIFO_STATUS.rx_ready，不是真正的 irq pending */
static int uart_bk7258_irq_is_pending(const struct device *dev)
{
    return uart_bk7258_irq_rx_ready(dev);
}

/* 改后 — 用 irq_update 保存的状态 */
static int uart_bk7258_irq_is_pending(const struct device *dev)
{
    struct uart_bk7258_data *data = dev->data;
    return (data->irq_status & BK7258_UART_RX_IRQ_BITS) ? 1 : 0;
}
```

同时因为你改了 `irq_update` 返回 real status，`uart_console_isr` 的 while 条件 `uart_irq_update() > 0` 现在也变成了只有在有真实 IRQ flag 时才进入循环。

### 第四步（关键）：初始化 rx_fifo_threshold

在 `uart_bk7258_init()` 或 `uart_bk7258_irq_rx_enable()` 中设置 RX FIFO threshold = 1：

```c
/* 在 uart_bk7258_init() 中添加 */
/* 设置 RX FIFO threshold = 1，否则默认 0 会导致 rx_fifo_need_read 永远为真 */
uint32_t fc = sys_read32(cfg->base + 0x14);  /* fifo_config offset */
fc &= ~(0xFF << 8);                           /* 清 rx_fifo_threshold 域 [15:8] */
fc |= (1 << 8);                                /* 设 threshold = 1 */
sys_write32(fc, cfg->base + 0x14);
```

如果加在 `irq_rx_enable` 中也可以，参考 SDK 做法：

```c
static void uart_bk7258_irq_rx_enable(const struct device *dev)
{
    const struct uart_bk7258_config *cfg = dev->config;
    struct uart_bk7258_data *data = dev->data;
    uint32_t val;

    data->rx_irq_enabled = true;

    /* 设 threshold = 1，避免 reset 值 0 导致永远 pending */
    val = sys_read32(cfg->base + 0x14);
    val &= ~(0xFF << 8);
    val |= (1 << 8);
    sys_write32(val, cfg->base + 0x14);

    /* 清旧 RX flag */
    sys_write32(BK7258_UART_RX_IRQ_BITS,
                cfg->base + BK7258_UART_INT_FLAG_OFFSET);

    /* 读回确认清干净了 (诊断) — 理想情况应读到 0 */
    val = sys_read32(cfg->base + BK7258_UART_INT_FLAG_OFFSET);
    if (val & BK7258_UART_RX_IRQ_BITS) {
        /* 二次清——如果这步还清不掉说明硬件 level 条件确实永远满足 */
        sys_write32(BK7258_UART_RX_IRQ_BITS,
                    cfg->base + BK7258_UART_INT_FLAG_OFFSET);
    }

    val = sys_read32(cfg->base + BK7258_UART_INT_ENABLE_OFFSET);
    val |= BK7258_UART_RX_IRQ_BITS;
    sys_write32(val, cfg->base + BK7258_UART_INT_ENABLE_OFFSET);
}
```

### 第五步：如果设了 threshold 后仍风暴，在 ISR 入口直接暴力清 flag

```c
static void uart_bk7258_isr(const struct device *dev)
{
    const struct uart_bk7258_config *cfg = dev->config;
    struct uart_bk7258_data *data = dev->data;

    /* 紧急：直接在 ISR 入口清 RX flag，看是否退风暴 */
    sys_write32(BK7258_UART_RX_IRQ_BITS,
                cfg->base + BK7258_UART_INT_FLAG_OFFSET);
    /* 读回确认 — 如果清完立刻又变回 1，确认是 threshold=0 问题 */
    if (sys_read32(cfg->base + BK7258_UART_INT_FLAG_OFFSET) & BK7258_UART_RX_IRQ_BITS) {
        uart_bk7258_poll_out(dev, 'S');  /* Stuck! */
    }

    if (data->callback) {
        data->callback(dev, data->callback_data);
    }
}
```

