};
```

在 `uart_bk7258_init()` 中 clock_control_on() 之后、配置 UART 寄存器之前插入：

```c
static int uart_bk7258_init(const struct device *dev)
{
    const struct uart_bk7258_config *cfg = dev->config;
    int ret;

    /* 1) clock gate */
    if (cfg->clk_dev != NULL) {
        ret = clock_control_on(cfg->clk_dev, cfg->clk_id);
        if (ret != 0) return ret;
    }

    /* 2) pinctrl ─ 双保险：即使 bootloader 已配好，再确认一次 */
    ret = pinctrl_apply_state(cfg->pcfg, PINCTRL_STATE_DEFAULT);
    if (ret != 0) return ret;

    /* 3) UART 硬件寄存器配置 (baudrate, databits, rx/tx enable) */
    // ... 现有代码 ...
}
```

修改 `UART_BK7258_INIT` 宏，在 config 初始化中加入 pcfg：

```c
#define UART_BK7258_INIT(inst)                                \
    UART_BK7258_IRQ_CONFIG_FUNC(inst)                         \
    PINCTRL_DT_INST_DEFINE(inst)                              \  /* <-- 新增 */
                                                              \
    static const struct uart_bk7258_config uart_bk7258_config_##inst = { \
        .base = DT_INST_REG_ADDR(inst),                       \
        .current_speed = DT_INST_PROP(inst, current_speed),   \
        .clk_dev = DEVICE_DT_GET(DT_CLOCKS_CTLR(DT_DRV_INST(inst))), \
        .clk_id = (clock_control_subsys_t)(uintptr_t)DT_CLOCKS_CELL(DT_DRV_INST(inst), id), \
        .pcfg = PINCTRL_DT_INST_DEV_CONFIG_GET(inst),         \  /* <-- 新增 */
        UART_BK7258_IRQ_CONFIG_INIT(inst)                     \
    };                                                        \
    /* ... 其余不变 ... */
```

注意：`PINCTRL_DT_INST_DEFINE(inst)` 必须放在使用它的 config struct 之前（C 要求变量定义在使用之前）。此宏展开为 `static const struct pinctrl_dev_config` 变量定义。

